"use client";

import { useEffect, useState } from 'react';
import Navbar from '../components/Navbar';
import Hero from '../components/Hero';
import About from '../components/About';
import StudioSpace from '../components/StudioSpace';
import Artists from '../components/Artists';
import SoundLibrary from '../components/SoundLibrary';
import Scheduler from '../components/Scheduler';
import Contact from '../components/Contact';

export default function Home() {
  const [activeSection, setActiveSection] = useState('');

  useEffect(() => {
    const handleScroll = () => {
      const sections = ['about', 'studio', 'artists', 'music', 'scheduler'];
      const scrollPosition = window.scrollY + 200; // offset for nav trigger

      for (const section of sections) {
        const el = document.getElementById(section);
        if (el) {
          const top = el.offsetTop;
          const height = el.offsetHeight;
          if (scrollPosition >= top && scrollPosition < top + height) {
            setActiveSection(section);
            break;
          }
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <>
      {/* Background Floating Ambient Light Elements */}
      <div className="ambient-glow-1"></div>
      <div className="ambient-glow-2"></div>

      {/* Navigation Header */}
      <Navbar activeSection={activeSection} />

      <main>
        {/* Hero Banner */}
        <Hero />

        {/* Narrative / About */}
        <About />

        {/* Physical Studio Setup */}
        <StudioSpace />

        {/* Artists Roster */}
        <Artists />

        {/* Releases & Visualizer Player */}
        <SoundLibrary />

        {/* Google Calendar Interactive Booking Form */}
        <Scheduler />
      </main>

      {/* Footer and Contacts */}
      <Contact />
    </>
  );
}
